9	/*
10	    This inline function was designed to get the table info and bias value for
11	   current input xx! lower:      indicate the lower boundary of the first table;
12	    upper:      indicate the upper boundary of the first table as well as the
13	   lower boundary of the second table; max:        indicate the upper boundary
14	   of the second table; stride0:    indicate the stride of the first table;
15	    stride1:    indicate the stride of the second table;
16	    xx:         indicate the inputs value;
17	    table_idx:  indicate the location of table info of input value xx;
18	*/
19	template <typename FPTYPE>
20	inline void locate_xx(const FPTYPE& lower,
21	                      const FPTYPE& upper,
22	                      const FPTYPE& max,
23	                      const FPTYPE& stride0,
24	                      const FPTYPE& stride1,
25	                      FPTYPE& xx,
26	                      int& table_idx) {
27	  if (xx < lower) {
28	    table_idx = 0;
29	    xx = (FPTYPE)0.;
30	  } else if (xx < upper) {
31	    table_idx = (int)((xx - lower) / stride0);
32	    xx -= (table_idx * stride0 + lower);
33	  } else if (xx < max) {
34	    int first_stride = int((upper - lower) / stride0);
35	    table_idx = first_stride + (int)((xx - upper) / stride1);
36	    xx -= ((table_idx - first_stride) * stride1 + upper);
37	  } else {
38	    table_idx =
39	        int((upper - lower) / stride0) + (int)((max - upper) / stride1) - 1;
40	    xx = (FPTYPE)0.;
41	  }
42	}
