429	template <typename FPTYPE>
430	void deepmd::tabulate_fusion_se_t_grad_cpu(FPTYPE* dy_dem_x,
431	                                           FPTYPE* dy_dem,
432	                                           const FPTYPE* table,
433	                                           const FPTYPE* table_info,
434	                                           const FPTYPE* em_x,
435	                                           const FPTYPE* em,
436	                                           const FPTYPE* dy,
437	                                           const int nloc,
438	                                           const int nnei_i,
439	                                           const int nnei_j,
440	                                           const int last_layer_size) {
441	  memset(dy_dem_x, 0, sizeof(FPTYPE) * nloc * nnei_i * nnei_j);
442	  memset(dy_dem, 0, sizeof(FPTYPE) * nloc * nnei_i * nnei_j);
443	  FPTYPE const lower = table_info[0];
444	  FPTYPE const upper = table_info[1];
445	  FPTYPE const _max = table_info[2];
446	  FPTYPE const stride0 = table_info[3];
447	  FPTYPE const stride1 = table_info[4];
448	// for every atom, execute a small gemm~
449	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
450	#pragma omp parallel for
451	  for (int ii = 0; ii < nloc; ii++) {
452	    FPTYPE ll = (FPTYPE)0.;
453	    FPTYPE rr = (FPTYPE)0.;
454	    for (int jj = 0; jj < nnei_i; jj++) {
455	      for (int kk = 0; kk < nnei_j; kk++) {
456	        // construct the dy/dx
457	        FPTYPE xx = em_x[ii * nnei_i * nnei_j + jj * nnei_j + kk];
458	        ll = xx;
459	        int table_idx = 0;
460	        locate_xx_se_t(lower, upper, -_max, _max, stride0, stride1, xx,
461	                       table_idx);
462	        FPTYPE grad = (FPTYPE)0.0;
463	        for (int mm = 0; mm < last_layer_size; mm++) {
464	          rr = dy[ii * last_layer_size + mm];
465	          FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * mm + 0];
466	          FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * mm + 1];
467	          FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * mm + 2];
468	          FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * mm + 3];
469	          FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * mm + 4];
470	          FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * mm + 5];
471	          FPTYPE res =
472	              a0 + (a1 + (a2 + (a3 + (a4 + a5 * xx) * xx) * xx) * xx) * xx;
473	
474	          grad += (a1 + ((FPTYPE)2. * a2 +
475	                         ((FPTYPE)3. * a3 +
476	                          ((FPTYPE)4. * a4 + (FPTYPE)5. * a5 * xx) * xx) *
477	                             xx) *
478	                            xx) *
479	                  ll * rr;
480	          dy_dem[ii * nnei_i * nnei_j + jj * nnei_j + kk] += res * rr;
481	        }
482	        dy_dem_x[ii * nnei_i * nnei_j + jj * nnei_j + kk] = grad;
483	      }
484	    }
485	  }
