// Float-instantiation coherence check: same table response math must hold in
// single precision (looser tolerances, FP32 finite differences).
#include "tabulate.h"

#include <cmath>
#include <cstdio>
#include <vector>

int main() {
  const int L = 3;
  // arbitrary coefficients (no Hermite needed: coherence is local), two
  // sub-table layout with non-binary strides
  const float lower = 0.0f, upper = 1.2f, maxv = 2.4f, s0 = 0.3f, s1 = 0.4f;
  const int n0 = (int)((upper - lower) / s0 + 0.5f);
  const int n1 = (int)((maxv - upper) / s1 + 0.5f);
  std::vector<float> tab((n0 + n1) * L * 6);
  unsigned st = 12345;
  auto rnd = [&]() {
    st = st * 1664525u + 1013904223u;
    return (float)(st >> 8) / (float)(1u << 24) * 2.0f - 1.0f;
  };
  for (auto& v : tab) v = rnd();
  const std::vector<float> ti = {lower, upper, maxv, s0, s1, -1.0f};
  const float w[L] = {0.7f, -0.4f, 0.2f};
  auto value = [&](float x) {
    float out[8];
    deepmd::tabulate_fusion_se_r_cpu<float>(out, tab.data(), ti.data(), &x, 1,
                                            1, L);
    float e = 0;
    for (int m = 0; m < L; ++m) e += out[m] * w[m];
    return e;
  };
  const float h = 1e-2f;
  float worst = 0;
  for (float x = lower - 0.4f; x < maxv + 0.4f; x += 0.05f) {
    float dy;
    deepmd::tabulate_fusion_se_r_grad_cpu<float>(&dy, tab.data(), ti.data(),
                                                 &x, w, 1, 1, L);
    const float fd = (value(x + h) - value(x - h)) / (2 * h);
    const float err = std::fabs(dy - fd) / (1.0f + std::fabs(fd));
    if (err > worst) worst = err;
  }
  std::printf("float worst rel err = %.4e -> %s\n", (double)worst,
              worst < 1e-2f ? "PASS" : "FAIL");
  return worst < 1e-2f ? 0 : 1;
}

